inputs = ['kdwgck', 'ev', 'xav', 'zdej', 'dkwjdd']
outputs = ['kdwgck', 'ev', 'xav', 'zdz', 'dkwijdd']

# Let's trace through each pair to understand the exact changes
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Input {i}: '{inp}' -> Output {i}: '{outp}'")

    # Check what changed character by character
    min_len = min(len(inp), len(outp))
    for j in range(max(len(inp), len(outp))):
        if j >= len(inp):
            print(f"  Position {j}: Added '{outp[j]}'")
        elif j >= len(outp):
            print(f"  Position {j}: Removed '{inp[j]}'")
        elif inp[j] != outp[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        else:
            print(f"  Position {j}: '{inp[j]}' unchanged")
    print()

